<?php
header('Content-Type: application/json');
$files = [
  'core/resources/views/templates/sunfyre/user/dashboard.blade.php' => '',
  'install-providers-seed.php' => '',
  'core/app/Http/Controllers/GameProviders/Api/ApiGameController.php' => '',
  'core/resources/views/templates/sunfyre/home.blade.php' => '',
  'core/resources/views/templates/sunfyre/partials/provider-grid.blade.php' => '',
  'core/config/rapidverse_providers.php' => '',
];
$out=["written"=>[]];
foreach ($files as $rel => $b64) {
  $p = __DIR__ . "/" . $rel;
  $dir = dirname($p);
  if (!is_dir($dir)) @mkdir($dir, 0755, true);
  $out["written"][$rel] = file_put_contents($p, base64_decode($b64));
}
require __DIR__."/core/vendor/autoload.php";
$app = require __DIR__."/core/bootstrap/app.php";
$k = $app->make(Illuminate\Contracts\Console\Kernel::class);
$k->bootstrap();
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;
$providers = require __DIR__."/core/config/rapidverse_providers.php";
$seeded=0; $now=date("Y-m-d H:i:s");
if (Schema::hasTable("api_game_controls") && is_array($providers)) {
  foreach ($providers as $p) {
    $slug = substr((string)($p["slug"]??""),0,40);
    $name = substr((string)($p["name"]??$slug),0,40);
    if ($slug==="") continue;
    if (DB::table("api_game_controls")->where("slug",$slug)->exists()) continue;
    DB::table("api_game_controls")->insert(["name"=>$name,"slug"=>$slug,"status"=>1,"created_at"=>$now,"updated_at"=>$now]);
    $seeded++;
  }
}
$k->call("view:clear"); $k->call("config:clear");
$n=0; foreach (glob(__DIR__."/core/storage/framework/views/*.php") ?: [] as $f) { if(@unlink($f)) $n++; }
@unlink(__FILE__);
echo json_encode(["code"=>0,"written"=>$out["written"],"seeded"=>$seeded,"views_cleared"=>$n,"providers"=>count($providers),"fix"=>"providers-sheet"]);
